use std::sync::{Arc, Mutex, atomic::{AtomicBool, Ordering}};

struct SharedResource {
    data: Arc<Mutex<Vec<u8>>>,
    alive: Arc<AtomicBool>,
    consumer_count: Arc<std::sync::atomic::AtomicUsize>,
}

impl SharedResource {
    fn new() -> Self {
        SharedResource {
            data: Arc::new(Mutex::new(Vec::new())),
            alive: Arc::new(AtomicBool::new(true)),
            consumer_count: Arc::new(std::sync::atomic::AtomicUsize::new(0)),
        }
    }

    fn acquire_consumer(&self) -> ResourceHandle {
        self.consumer_count.fetch_add(1, Ordering::SeqCst);
        ResourceHandle {
            data: self.data.clone(),
            alive: self.alive.clone(),
            consumer_count: self.consumer_count.clone(),
        }
    }
}

struct ResourceHandle {
    data: Arc<Mutex<Vec<u8>>>,
    alive: Arc<AtomicBool>,
    consumer_count: Arc<std::sync::atomic::AtomicUsize>,
}

impl ResourceHandle {
    fn is_alive(&self) -> bool {
        self.alive.load(Ordering::SeqCst)
    }
}

impl Drop for ResourceHandle {
    fn drop(&mut self) {
        let remaining = self.consumer_count.fetch_sub(1, Ordering::SeqCst);
        // Last consumer triggers cleanup
        if remaining == 1 {
            self.alive.store(false, Ordering::SeqCst);
        }
    }
}

impl Drop for SharedResource {
    fn drop(&mut self) {
        // Wait until all consumers finish before cleanup
        while self.consumer_count.load(Ordering::SeqCst) > 0 {
            std::thread::yield_now();
        }
        self.alive.store(false, Ordering::SeqCst);
    }
}

// Safe usage: resource outlives all consumers
let resource = SharedResource::new();
let handle = resource.acquire_consumer();

std::thread::spawn(move || {
    if handle.is_alive() {
        let mut data = handle.data.lock().unwrap();
        data.push(1); // Safe: handle keeps resource alive
    }
    // ResourceHandle::Drop decrements consumer count
});

// Resource::Drop waits for all consumers to finish
